<!doctype html>
<html lang="en" data-theme="paper">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Platinum Road — GTA VI Trophy Guide &amp; Tracker</title>
<link rel="stylesheet" href="style.css">
</head>
<body>
<header class="topbar">
  <div class="brand">
    <div class="brand-mark" aria-hidden="true">VI</div>
    <div>
      <h1>Platinum Road</h1>
      <p class="subtitle">Grand Theft Auto VI &middot; 55 PS5 trophies &middot; guide, roadmap &amp; tracker</p>
    </div>
  </div>
  <div class="top-actions">
    <button id="spoilerBtn" type="button" class="pill" aria-pressed="false" title="Hide story trophy names and descriptions until earned">Spoiler-safe: off</button>
    <button id="themeBtn" type="button" class="pill" title="Switch paper / night theme">Night theme</button>
  </div>
</header>

<section class="dashboard" aria-label="Progress">
  <div class="progress-block">
    <div class="ring" id="ring" style="--p:0"><span id="ringText">0%</span></div>
    <div>
      <p class="big" id="progressText">0 of 55 earned</p>
      <p class="muted" id="progressSub">Your road to the platinum starts with the story.</p>
    </div>
  </div>
  <div class="grade-counts" id="gradeCounts"></div>
  <div class="missable-callout"><strong id="missableCount">9 missable</strong><span>Save before each flagged beat — one missed moment can cost a playthrough.</span></div>
</section>

<nav class="tabs" aria-label="Views">
  <button type="button" class="tab active" data-view="checklist">Checklist</button>
  <button type="button" class="tab" data-view="roadmap">Roadmap to Platinum</button>
  <button type="button" class="tab" data-view="missables">Missables <span class="tab-badge">9</span></button>
  <button type="button" class="tab" data-view="save">Save &amp; Sources</button>
</nav>

<main>
  <section id="view-checklist" class="view active">
    <div class="toolbar">
      <input id="search" type="search" placeholder="Search trophies, missions, guides…" aria-label="Search trophies">
      <div class="chips" id="chips" role="group" aria-label="Filter by kind"></div>
      <label class="grade-pick">Grade
        <select id="gradeSel">
          <option value="all">All grades</option>
          <option value="platinum">Platinum</option>
          <option value="gold">Gold</option>
          <option value="silver">Silver</option>
          <option value="bronze">Bronze</option>
        </select>
      </label>
      <label class="check"><input id="hideEarned" type="checkbox"> Hide earned</label>
    </div>
    <p class="list-meta" id="listMeta"></p>
    <div class="split">
      <ul class="trophy-list" id="trophyList"></ul>
      <aside class="detail" id="detail" aria-label="Trophy guide"></aside>
    </div>
  </section>

  <section id="view-roadmap" class="view">
    <p class="intro">Five phases, in order. Story first — the finale is a point of no return — then strangers, activities, collectibles, and the crime-spree cleanup last. Every step names the trophy it earns, and every missable beat is flagged with the save to keep.</p>
    <ol class="phases" id="phases"></ol>
  </section>

  <section id="view-missables" class="view">
    <p class="intro">Nine trophies are tied to a one-time story beat, a partner who may leave, or a single clean attempt. Keep a manual save before each one. Everything else can be cleaned up after the story.</p>
    <div class="miss-grid" id="missGrid"></div>
  </section>

  <section id="view-save" class="view">
    <div class="save-grid">
      <div class="card">
        <h2>Your progress</h2>
        <p>Progress is saved in this browser (localStorage) the moment you tick a trophy. Take it with you:</p>
        <div class="btn-row">
          <button id="exportBtn" type="button" class="btn">Export progress (.json)</button>
          <label class="btn ghost">Import progress <input id="importFile" type="file" accept="application/json" hidden></label>
          <button id="resetBtn" type="button" class="btn danger">Reset all progress</button>
        </div>
        <p class="muted" id="saveState"></p>
      </div>
      <div class="card">
        <h2>Sources &amp; honesty</h2>
        <p>Names, descriptions and grades are the official 55-trophy list as published (via Exophase, list dated 2026-11-18). Target counts — 250 stunts, 42 Shooting Range challenges, 14 drone race locations, 18 meditation spots, 100 WAiNK locations, 52 areas, 9 gangs, 8 garages, 500 choices — are the counts PSNProfiles lists for those official descriptions.</p>
        <p>Every guide is written in our own words for this entry and names its sources beside the trophy. Where a location or an exact trigger cannot be confirmed from the official description, the guide says so plainly (“not yet verified”) instead of inventing a step.</p>
        <p class="muted">No Rockstar logo or official artwork is used anywhere in this guide; the look is our own. This app makes no network requests — it runs fully offline from its own files.</p>
      </div>
    </div>
  </section>
</main>

<footer>
  <p>Platinum Road — an unofficial fan-made guide. Grand Theft Auto and GTA are trademarks of Take-Two Interactive; this guide is not affiliated with or endorsed by Rockstar Games. Trophy names &amp; descriptions: official list via Exophase. Counts: PSNProfiles. Guides: our own words.</p>
</footer>

<script type="module" src="app.js"></script>
</body>
</html>
```

### app/app.js (16757 bytes)

```js
// Platinum Road — GTA VI trophy guide & tracker. Static, offline: the only
// fetch is the trophy data file sitting beside this script. Progress lives in
// localStorage and can be exported / imported as JSON. URL params (for the
// screenshots and for sharing a view): ?demo=1 seeds 13 earned trophies,
// ?view=roadmap|missables|save, ?open=<id>, ?filter=<chip>, ?spoiler=1,
// ?theme=night.
const KEY = 'gta6-platinum-road-v1';
const DEMO_EARNED = [2, 3, 8, 15, 16, 19, 21, 28, 33, 35, 42, 44, 46];
const params = new URLSearchParams(location.search);

const FILTERS = [
  ['all', 'All 55'],
  ['story', 'Story'],
  ['missable', 'Missable'],
  ['collectibles', 'Collectibles'],
  ['activities', 'Activities'],
  ['strangers', 'Strangers'],
  ['crime', 'Crime'],
  ['misc', 'Misc'],
];
const FILTER_CATS = {
  story: ['story', 'mission', 'platinum', 'completion'],
  collectibles: ['collectible'],
  activities: ['activity'],
  strangers: ['stranger'],
  crime: ['crime'],
  misc: ['misc'],
};

const PHASES = [
  { n: 1, title: 'Story first', blurb: 'Play Chapters 1–4 and every named mission in order. Chapter trophies are progress markers — nothing to grind, just finish the story beats.', ids: [2, 3, 4, 5, 6, 8, 9, 10, 11, 12, 13, 44, 47] },
  { n: 2, title: 'Partners & strangers', blurb: 'Finish the stranger strands while partners are still around. The two partner trophies are missable — do them now, not after the finale.', ids: [22, 23, 24, 26, 27, 25, 29, 33, 34] },
  { n: 3, title: 'Activities & skills', blurb: 'One attempt at each activity type, then the skill grinds: gold medals at the range, drone races, and the stunt counter.', ids: [16, 21, 46, 20, 28, 18, 19, 15, 17, 32, 36, 51] },
  { n: 4, title: 'Collectibles & exploration', blurb: 'Sweep the map region by region: cards, WAiNK points, vehicles, areas, garages, and the Scooter Bros registrations — all in the same trips.', ids: [30, 31, 35, 42, 54, 55] },
  { n: 5, title: 'Crime spree & cleanup', blurb: 'Heists, vaults and gang operations, the money trophies, the one-off oddities — then the finale, 100% completion, and the platinum.', ids: [39, 37, 45, 40, 41, 43, 52, 53, 48, 49, 50, 38, 14, 7, 1] },
];
const PHASE_NOTES = {
  2: 'Opening mission — pops in the first hour.',
  3: 'Finish Chapter 1.',
  4: 'Finish Chapter 2.',
  5: 'Finish Chapter 3.',
  6: 'Finish Chapter 4 — last chapter before the finale.',
  8: 'Mission: Breakfast Run.',
  9: 'Mission: The Cartel Heist.',
  10: 'Mission: Child’s Play.',
  11: 'Mission: Headliners.',
  12: 'Mission: VCIA Takedown.',
  13: 'Mission: Operation Savage Glory.',
  44: 'Cocktail on Ocean Beach — do it the first time you are there.',
  47: 'Partnership beat — keep a save around partner story moments.',
  22: 'Andy’s final mission.',
  23: 'Kenton’s final mission.',
  24: 'Billy’s final mission.',
  26: 'Randy’s final mission.',
  27: 'Tyrone’s final mission.',
  25: 'Finish any 8 stranger strands in total.',
  29: 'Hunt Bret’s unique animal.',
  33: 'MISSABLE — 4-star wanted level with your partner.',
  34: 'MISSABLE — rob 3 shops in a row with your partner.',
  16: 'Try all 9 activity types once.',
  21: 'Finish one arcade game.',
  46: 'A game of bowling at Kolt & Associates.',
  20: 'Out-fish Cal.',
  28: 'Meditate at all 18 spots.',
  18: 'Win a drone race at all 14 locations.',
  19: 'Win 20 different races.',
  15: 'Land 250 stunts.',
  17: 'Gold all 42 Shooting Range challenges.',
  32: 'Complete 50 challenges.',
  36: '5 takedowns in one Combat Focus.',
  51: 'A melee drive-by takedown.',
  30: 'Complete 3 card sets.',
  31: 'WAiNK It at 100 locations.',
  35: 'Discover 100 vehicles.',
  42: 'Explore all 52 areas.',
  54: 'Buy all 8 garages.',
  55: 'Register 10 vehicles in the Scooter Bros app.',
  39: 'MISSABLE — undetected jewelry store robbery; save first.',
  37: 'Unscheduled departure from VCIA.',
  45: 'Smash out of a vehicle showroom.',
  40: 'Rob 5 bank vaults and escape.',
  41: 'Rob an armored truck and escape.',
  43: 'One illegal operation per gang (9 gangs).',
  52: 'Launder $250,000 in Marked Bills.',
  53: 'Spend $100,000 across shops.',
  48: 'MISSABLE — 500 choices, some one-time.',
  49: 'MISSABLE — succeed on the second attempt.',
  50: 'MISSABLE — witness the strange event.',
  38: 'Deal with the Rhino tanks.',
  14: 'Reach 100% completion.',
  7: 'MISSABLE — the final mission; do cleanup first.',
  1: 'The platinum — earned when the other 54 are done.',
};

let doc;
try {
  doc = await (await fetch('data/trophies.json')).json();
} catch {
  document.getElementById('trophyList').innerHTML =
    '<li class="empty">Could not load data/trophies.json. Serve app/ over HTTP (node serve.ts) — file:// blocks the local fetch.</li>';
  throw new Error('trophies.json failed to load');
}
const trophies = doc.trophies;
const byId = new Map(trophies.map((t) => [t.id, t]));
const missable = trophies.filter((t) => t.missable);

function loadState() {
  try {
    const saved = JSON.parse(localStorage.getItem(KEY) ?? 'null');
    if (saved && Array.isArray(saved.earned)) return saved;
  } catch { /* corrupted save: start fresh */ }
  return { earned: [], spoiler: false, theme: 'paper' };
}
let state = loadState();
if (params.get('demo') === '1' && state.earned.length === 0) state.earned = [...DEMO_EARNED];
if (params.get('spoiler') === '1') state.spoiler = true;
if (params.get('theme') === 'night') state.theme = 'night';
let earned = new Set(state.earned);
let filter = params.get('filter') || 'all';
if (!FILTERS.some(([f]) => f === filter)) filter = 'all';
let gradeFilter = 'all';
let hideEarned = false;
let query = '';
let view = params.get('view') || 'checklist';
if (!['checklist', 'roadmap', 'missables', 'save'].includes(view)) view = 'checklist';
let selectedId = Number(params.get('open') || '') || (trophies.find((t) => !earned.has(t.id))?.id ?? 1);

function save() {
  state.earned = [...earned].sort((a, b) => a - b);
  state.spoiler = spoilerOn;
  state.theme = theme;
  localStorage.setItem(KEY, JSON.stringify(state));
}

let spoilerOn = state.spoiler;
let theme = state.theme || 'paper';

const CAT_LABEL = { platinum: 'goal', completion: '100%', story: 'story', mission: 'mission', stranger: 'stranger', collectible: 'collectible', activity: 'activity', crime: 'crime', misc: 'misc' };
const catLabel = (t) => CAT_LABEL[t.category] ?? t.category;
const $ = (id) => document.getElementById(id);
const isStory = (t) => t.category === 'story' || t.category === 'mission';
const hiddenBySpoiler = (t) => spoilerOn && isStory(t) && !earned.has(t.id);
const displayName = (t) => (hiddenBySpoiler(t) ? 'Hidden story trophy' : t.name);
const displayDesc = (t) =>
  hiddenBySpoiler(t)
    ? 'Spoiler-safe: earn this trophy to reveal its official name and description.'
    : t.description;

function gradeLabel(g) { return g[0].toUpperCase() + g.slice(1); }

function renderDashboard() {
  const total = trophies.length;
  const n = earned.size;
  const pct = Math.round((n / total) * 100);
  $('ring').style.setProperty('--p', pct);
  $('ringText').textContent = `${pct}%`;
  $('progressText').textContent = `${n} of ${total} earned`;
  $('progressSub').textContent =
    n === 0 ? 'Your road to the platinum starts with the story.'
    : n === total ? 'Platinum earned. Leonida Legend.'
    : `${total - n} to go — next: ${trophies.find((t) => !earned.has(t.id))?.name ?? ''}.`;
  $('missableCount').textContent = `${missable.length} missable`;
  const counts = {};
  for (const g of ['platinum', 'gold', 'silver', 'bronze']) {
    counts[g] = trophies.filter((t) => t.grade === g && earned.has(t.id)).length;
  }
  $('gradeCounts').innerHTML = ['platinum', 'gold', 'silver', 'bronze']
    .map((g) => {
      const tot = trophies.filter((t) => t.grade === g).length;
      return `<div class="grade-chip ${g}"><b>${counts[g]}/${tot}</b>${gradeLabel(g)}</div>`;
    })
    .join('');
  $('saveState').textContent = `${earned.size} trophies earned · saved in this browser · ${new Date().toLocaleDateString()}`;
}

function visibleTrophies() {
  return trophies.filter((t) => {
    if (filter === 'missable' && !t.missable) return false;
    if (filter !== 'all' && filter !== 'missable' && !FILTER_CATS[filter].includes(t.category)) return false;
    if (gradeFilter !== 'all' && t.grade !== gradeFilter) return false;
    if (hideEarned && earned.has(t.id)) return false;
    if (query) {
      const hay = `${t.name} ${t.description} ${t.guide}`.toLowerCase();
      if (!hay.includes(query)) return false;
    }
    return true;
  });
}

function renderChips() {
  $('chips').innerHTML = FILTERS.map(([f, label]) => {
    const n = f === 'all' ? trophies.length
      : f === 'missable' ? missable.length
      : trophies.filter((t) => FILTER_CATS[f].includes(t.category)).length;
    return `<button type="button" class="chip${filter === f ? ' active' : ''}" data-filter="${f}">${label} · ${n}</button>`;
  }).join('');
  document.querySelectorAll('#chips .chip').forEach((b) =>
    b.addEventListener('click', () => { filter = b.dataset.filter; renderChips(); renderList(); }));
}

function renderList() {
  const list = visibleTrophies();
  $('listMeta').textContent = `Showing ${list.length} of ${trophies.length} trophies` +
    (spoilerOn ? ' · spoiler-safe on: unrevealed story trophies are hidden until earned' : '');
  const ul = $('trophyList');
  ul.replaceChildren();
  if (!list.length) {
    ul.innerHTML = '<li class="empty">No trophies match these filters. Clear the search or pick another filter.</li>';
  }
  for (const t of list) {
    const li = document.createElement('li');
    li.className = `trophy${earned.has(t.id) ? ' earned' : ''}${selectedId === t.id ? ' selected' : ''}`;
    const box = document.createElement('input');
    box.type = 'checkbox';
    box.checked = earned.has(t.id);
    box.setAttribute('aria-label', `Mark ${displayName(t)} earned`);
    box.addEventListener('change', (e) => {
      e.stopPropagation();
      if (box.checked) earned.add(t.id); else earned.delete(t.id);
      save(); renderDashboard(); renderList(); renderDetail();
    });
    const main = document.createElement('div');
    const name = document.createElement('div');
    name.className = 't-name';
    name.textContent = displayName(t);
    const desc = document.createElement('div');
    desc.className = 't-desc';
    desc.textContent = displayDesc(t);
    const tags = document.createElement('div');
    tags.className = 't-tags';
    tags.innerHTML =
      `<span class="tag grade-${t.grade}">${t.grade}</span>` +
      (t.missable ? '<span class="tag miss">⚑ Missable</span>' : '') +
      `<span class="tag">${catLabel(t)}</span>`;
    main.append(name, desc, tags);
    const grade = document.createElement('div');
    grade.className = 't-grade';
    grade.textContent = `#${t.id}`;
    li.append(box, main, grade);
    li.addEventListener('click', (e) => {
      if (e.target === box) return;
      selectedId = t.id;
      renderList(); renderDetail();
    });
    ul.append(li);
  }
}

function renderDetail() {
  const t = byId.get(selectedId) ?? trophies[0];
  const d = $('detail');
  const hidden = hiddenBySpoiler(t);
  d.innerHTML = '';
  const h = document.createElement('h2');
  h.textContent = displayName(t);
  const meta = document.createElement('p');
  meta.className = 'muted';
  meta.textContent = `#${t.id} · ${gradeLabel(t.grade)} trophy · ${t.category}${t.missable ? ' · ⚑ Missable' : ''}`;
  d.append(h, meta);
  if (t.missable) {
    const banner = document.createElement('div');
    banner.className = 'miss-banner';
    banner.textContent = `⚑ Missable — ${t.missable_reason ?? 'tied to a one-time story beat. Keep a manual save first.'}`;
    d.append(banner);
  }
  const off = document.createElement('div');
  off.className = 'official';
  off.innerHTML = '<div class="label">Official description</div>';
  const od = document.createElement('p');
  od.textContent = displayDesc(t);
  off.append(od);
  d.append(off);
  if (!hidden) {
    const gl = document.createElement('div');
    gl.className = 'label';
    gl.textContent = 'Guide — our words';
    const g = document.createElement('p');
    g.className = 'guide-text';
    g.textContent = t.guide;
    const src = document.createElement('div');
    src.className = 'sources';
    src.innerHTML = '<div class="label">Sources cited</div>';
    const ul = document.createElement('ul');
    for (const s of t.sources) {
      const li = document.createElement('li');
      li.textContent = s;
      ul.append(li);
    }
    src.append(ul);
    d.append(gl, g, src);
  } else {
    const p = document.createElement('p');
    p.className = 'muted';
    p.textContent = 'Spoiler-safe is on. Tick this trophy earned (or turn spoiler-safe off) to reveal its guide and sources.';
    d.append(p);
  }
  const row = document.createElement('div');
  row.className = 'btn-row';
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'btn';
  btn.textContent = earned.has(t.id) ? '✓ Earned — unmark' : 'Mark as earned';
  btn.addEventListener('click', () => {
    if (earned.has(t.id)) earned.delete(t.id); else earned.add(t.id);
    save(); renderDashboard(); renderList(); renderDetail();
  });
  row.append(btn);
  d.append(row);
}

function renderRoadmap() {
  $('phases').innerHTML = PHASES.map((ph) => {
    const steps = ph.ids.map((id) => {
      const t = byId.get(id);
      const note = PHASE_NOTES[id] ?? '';
      const flag = t.missable ? ' <span class="warn">⚑ Missable</span>' : '';
      return `<li><b>${t.name}</b> — ${note}${flag}</li>`;
    }).join('');
    return `<li class="phase"><div class="phase-num">Phase<span>${ph.n}</span></div><div><h3>${ph.title} · ${ph.ids.length} trophies</h3><p class="muted">${ph.blurb}</p><ul>${steps}</ul></div></li>`;
  }).join('');
}

function renderMissables() {
  $('missGrid').innerHTML = missable.map((t) => {
    const li = t.sources.map((s) => `<li>${s}</li>`).join('');
    return `<article class="miss-card"><h3>${t.name}</h3><p class="why">⚑ ${t.missable_reason ?? ''}</p><p>${t.description}</p><p class="muted">${t.guide}</p><div class="sources"><div class="label">Sources</div><ul>${li}</ul></div></article>`;
  }).join('');
}

function applyTheme() {
  document.documentElement.dataset.theme = theme;
  $('themeBtn').textContent = theme === 'night' ? 'Paper theme' : 'Night theme';
}
function applySpoiler() {
  $('spoilerBtn').setAttribute('aria-pressed', String(spoilerOn));
  $('spoilerBtn').textContent = spoilerOn ? 'Spoiler-safe: on' : 'Spoiler-safe: off';
}
function setView(v) {
  view = v;
  document.querySelectorAll('.tab').forEach((b) => b.classList.toggle('active', b.dataset.view === v));
  document.querySelectorAll('.view').forEach((s) => s.classList.toggle('active', s.id === `view-${v}`));
}

document.querySelectorAll('.tab').forEach((b) => b.addEventListener('click', () => setView(b.dataset.view)));
$('themeBtn').addEventListener('click', () => { theme = theme === 'night' ? 'paper' : 'night'; applyTheme(); save(); });
$('spoilerBtn').addEventListener('click', () => { spoilerOn = !spoilerOn; applySpoiler(); save(); renderList(); renderDetail(); });
$('search').addEventListener('input', (e) => { query = e.target.value.trim().toLowerCase(); renderList(); });
$('gradeSel').addEventListener('change', (e) => { gradeFilter = e.target.value; renderList(); });
$('hideEarned').addEventListener('change', (e) => { hideEarned = e.target.checked; renderList(); });
$('exportBtn').addEventListener('click', () => {
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([JSON.stringify({ game: 'GTA VI', earned: [...earned].sort((x, y) => x - y) }, null, 2)], { type: 'application/json' }));
  a.download = 'gta6-platinum-road-progress.json';
  a.click();
});
$('importFile').addEventListener('change', async (e) => {
  const file = e.target.files[0];
  if (!file) return;
  try {
    const data = JSON.parse(await file.text());
    const ids = Array.isArray(data) ? data : data.earned;
    const next = new Set(ids.filter((id) => byId.has(Number(id))).map(Number));
    earned = next;
    save(); renderDashboard(); renderList(); renderDetail();
  } catch {
    alert('That file is not a valid Platinum Road progress export.');
  }
  e.target.value = '';
});
$('resetBtn').addEventListener('click', () => {
  if (!confirm('Reset all 55 trophies to unearned?')) return;
  earned = new Set();
  save(); renderDashboard(); renderList(); renderDetail();
});

applyTheme();
applySpoiler();
renderDashboard();
renderChips();
renderList();
renderDetail();
renderRoadmap();
renderMissables();
setView(view);
save();
```

### app/style.css (9757 bytes)

```css
/* Platinum Road — paper by default, night on toggle. Serif display, sans body,
   coral accent. All colours come from theme variables; no external fonts. */
:root { color-scheme: light; }
html[data-theme="paper"] {
  --bg: #f6f3ee; --surface: #fffdf8; --surface-2: #efe9dd; --ink: #1c1712;
  --muted: #6d6355; --line: #ddd3c0; --accent: #d64b2a; --accent-ink: #fff;
  --gold: #8a6d00; --silver: #5f6b7a; --bronze: #8a5a2b; --platinum: #2f6f7e;
  --flag: #b3261e; --flag-bg: #fbe9e5; --ok: #2e7d32; --shadow: rgba(28, 23, 18, .12);
}
html[data-theme="night"] {
  color-scheme: dark;
  --bg: #0f1218; --surface: #171b24; --surface-2: #202634; --ink: #e9e4d8;
  --muted: #9aa1ad; --line: #2c3342; --accent: #ff6a3d; --accent-ink: #1c100a;
  --gold: #e3b505; --silver: #aab4c4; --bronze: #d99a5b; --platinum: #6fc3d4;
  --flag: #ff8a7a; --flag-bg: #3a1d18; --ok: #7ecb8a; --shadow: rgba(0, 0, 0, .4);
}
* { box-sizing: border-box; }
body {
  margin: 0; background: var(--bg); color: var(--ink);
  font: 15px/1.5 -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
h1, h2, h3, .serif { font-family: Georgia, "Times New Roman", serif; }
h1 { font-size: 30px; margin: 0; letter-spacing: .5px; }
h2 { font-size: 20px; margin: 0 0 8px; }
h3 { font-size: 16px; margin: 0 0 4px; }
p { margin: 0 0 10px; }
.muted { color: var(--muted); font-size: 13px; }
a { color: var(--accent); }

.topbar {
  display: flex; justify-content: space-between; align-items: center; gap: 16px;
  padding: 16px 24px 12px; border-bottom: 3px solid var(--accent);
  background: var(--surface);
}
.brand { display: flex; gap: 14px; align-items: center; }
.brand-mark {
  width: 52px; height: 52px; flex: none; display: grid; place-items: center;
  background: var(--accent); color: var(--accent-ink);
  font: 700 22px Georgia, serif; border-radius: 10px;
}
.subtitle { margin: 2px 0 0; color: var(--muted); font-size: 13px; }
.top-actions { display: flex; gap: 8px; }
.pill {
  border: 1px solid var(--line); background: var(--surface-2); color: var(--ink);
  border-radius: 999px; padding: 8px 14px; font: 600 13px inherit; cursor: pointer;
}
.pill[aria-pressed="true"] { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }

.dashboard {
  display: flex; gap: 24px; align-items: center; flex-wrap: wrap;
  padding: 16px 24px; background: var(--surface); border-bottom: 1px solid var(--line);
}
.progress-block { display: flex; gap: 16px; align-items: center; }
.ring {
  width: 84px; height: 84px; border-radius: 50%; flex: none; display: grid; place-items: center;
  background: conic-gradient(var(--accent) calc(var(--p) * 1%), var(--surface-2) 0);
  font: 700 17px Georgia, serif;
}
.ring span {
  width: 64px; height: 64px; border-radius: 50%; background: var(--surface);
  display: grid; place-items: center;
}
.big { font: 700 22px Georgia, serif; margin: 0; }
.grade-counts { display: flex; gap: 8px; flex-wrap: wrap; }
.grade-chip {
  border: 1px solid var(--line); border-radius: 8px; padding: 6px 10px;
  background: var(--surface); font-size: 13px; text-align: center;
}
.grade-chip b { display: block; font-size: 16px; }
.grade-chip.platinum b { color: var(--platinum); }
.grade-chip.gold b { color: var(--gold); }
.grade-chip.silver b { color: var(--silver); }
.grade-chip.bronze b { color: var(--bronze); }
.missable-callout {
  margin-left: auto; border: 1px solid var(--flag); background: var(--flag-bg);
  border-radius: 8px; padding: 8px 12px; font-size: 13px; max-width: 340px;
}
.missable-callout strong { color: var(--flag); margin-right: 6px; }

.tabs { display: flex; gap: 4px; padding: 0 24px; background: var(--surface); border-bottom: 1px solid var(--line); }
.tab {
  border: none; background: none; color: var(--muted); cursor: pointer;
  font: 700 14px inherit; padding: 12px 16px; border-bottom: 3px solid transparent;
}
.tab.active { color: var(--ink); border-bottom-color: var(--accent); }
.tab-badge {
  background: var(--flag); color: #fff; border-radius: 999px;
  font-size: 11px; padding: 1px 7px; margin-left: 2px;
}

main { padding: 18px 24px 8px; max-width: 1280px; margin: 0 auto; }
.view { display: none; }
.view.active { display: block; }
.intro { font-size: 15px; max-width: 900px; }

.toolbar { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; margin-bottom: 8px; }
.toolbar input[type="search"] {
  flex: 1 1 220px; padding: 9px 12px; border: 1px solid var(--line); border-radius: 8px;
  background: var(--surface); color: var(--ink); font: inherit;
}
.chips { display: flex; gap: 6px; flex-wrap: wrap; }
.chip {
  border: 1px solid var(--line); background: var(--surface); color: var(--ink);
  border-radius: 999px; padding: 6px 12px; font: 600 13px inherit; cursor: pointer;
}
.chip.active { background: var(--ink); color: var(--bg); border-color: var(--ink); }
.grade-pick, .check { font-size: 13px; color: var(--muted); display: flex; gap: 6px; align-items: center; }
.grade-pick select {
  padding: 7px 8px; border: 1px solid var(--line); border-radius: 8px;
  background: var(--surface); color: var(--ink); font: inherit;
}
.list-meta { color: var(--muted); font-size: 13px; margin: 0 0 10px; }

.split { display: grid; grid-template-columns: minmax(0, 7fr) minmax(300px, 5fr); gap: 18px; align-items: start; }
.trophy-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.trophy {
  display: grid; grid-template-columns: 30px 1fr auto; gap: 10px; align-items: start;
  background: var(--surface); border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px;
  cursor: pointer; box-shadow: 0 1px 2px var(--shadow);
}
.trophy:hover { border-color: var(--accent); }
.trophy.selected { border-color: var(--accent); outline: 2px solid var(--accent); outline-offset: -1px; }
.trophy.earned { opacity: .72; }
.trophy input { width: 20px; height: 20px; margin-top: 2px; accent-color: var(--accent); cursor: pointer; }
.trophy .t-name { font: 700 15px Georgia, serif; }
.trophy.earned .t-name { text-decoration: line-through; }
.trophy .t-desc { color: var(--muted); font-size: 13px; margin-top: 2px; }
.trophy .t-tags { display: flex; gap: 6px; margin-top: 6px; flex-wrap: wrap; }
.tag {
  font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .4px;
  border: 1px solid var(--line); border-radius: 999px; padding: 2px 8px; color: var(--muted);
}
.tag.miss { color: var(--flag); border-color: var(--flag); }
.tag.grade-platinum { color: var(--platinum); border-color: var(--platinum); }
.tag.grade-gold { color: var(--gold); border-color: var(--gold); }
.tag.grade-silver { color: var(--silver); border-color: var(--silver); }
.tag.grade-bronze { color: var(--bronze); border-color: var(--bronze); }
.trophy .t-grade { font-size: 12px; font-weight: 700; text-transform: capitalize; white-space: nowrap; padding-top: 3px; }
.empty { color: var(--muted); padding: 24px; text-align: center; }

.detail {
  position: sticky; top: 12px; background: var(--surface); border: 1px solid var(--line);
  border-radius: 12px; padding: 16px 18px; box-shadow: 0 2px 8px var(--shadow);
}
.detail h2 { font-size: 22px; }
.detail .official { border-left: 3px solid var(--accent); padding: 2px 0 2px 10px; margin: 10px 0; }
.detail .official .label, .detail .label { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .6px; color: var(--muted); }
.detail .guide-text { font-size: 15px; }
.detail .sources { font-size: 13px; background: var(--surface-2); border-radius: 8px; padding: 10px 12px; }
.detail .sources li { margin: 2px 0 2px 16px; }
.miss-banner {
  border: 1px solid var(--flag); background: var(--flag-bg); color: var(--flag);
  border-radius: 8px; padding: 8px 12px; font-size: 13px; margin: 10px 0;
}
.btn-row { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 12px; }
.btn {
  border: 1px solid var(--accent); background: var(--accent); color: var(--accent-ink);
  border-radius: 8px; padding: 9px 14px; font: 700 13px inherit; cursor: pointer;
}
.btn.ghost { background: var(--surface); color: var(--ink); border-color: var(--line); }
.btn.danger { background: none; color: var(--flag); border-color: var(--flag); }

.phases { list-style: none; margin: 0; padding: 0; display: grid; gap: 14px; }
.phase {
  background: var(--surface); border: 1px solid var(--line); border-radius: 12px; padding: 16px 18px;
  display: grid; grid-template-columns: 110px 1fr; gap: 16px;
}
.phase-num { font: 700 15px Georgia, serif; color: var(--accent); }
.phase-num span { display: block; font-size: 28px; }
.phase ul { margin: 8px 0 0; padding-left: 18px; }
.phase li { margin: 3px 0; font-size: 14px; }
.phase li b { font-family: Georgia, serif; }
.warn { color: var(--flag); font-weight: 700; }

.miss-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 12px; }
.miss-card { background: var(--surface); border: 1px solid var(--flag); border-radius: 10px; padding: 12px 14px; }
.miss-card h3 { font-size: 16px; }
.miss-card .why { font-size: 13px; color: var(--flag); font-weight: 600; }

.save-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; align-items: start; }
.card { background: var(--surface); border: 1px solid var(--line); border-radius: 12px; padding: 16px 18px; }

footer { padding: 16px 24px 24px; color: var(--muted); font-size: 12px; max-width: 1280px; margin: 0 auto; }

@media (max-width: 900px) {
  .split, .save-grid { grid-template-columns: 1fr; }
  .detail { position: static; }
  .phase { grid-template-columns: 1fr; }
  .missable-callout { margin-left: 0; }
  .topbar { flex-wrap: wrap; }
}
@media (max-width: 340px) {
  body { font-size: 14px; }
  h1 { font-size: 24px; }
  .dashboard { padding: 12px; }
  main { padding: 12px; }
}
